document.addEventListener("DOMContentLoaded",function(){document.querySelectorAll(".VT_postSlide").forEach((t,e)=>{const a=t.querySelectorAll("img");if(0===a.length)return;const n="VT_postSlide-"+e;let s=`\n            <div id="${n}" class="carousel slide overflow-hidden" data-bs-ride="carousel">\n                <div class="carousel-inner">`;a.forEach((t,a)=>{const n=t.closest("a");let l=t.getAttribute("data-src")||t.getAttribute("src");l&&"null"!==l||n&&(l=n.getAttribute("href"));const o=t.getAttribute("alt")||"",r=n?n.getAttribute("href"):l;s+=`\n                <div class="carousel-item ${0===a?"active":""}">\n                    <a href="${r}" data-fancybox="gallery-${e}" data-caption="${o}">\n                        <img loading="lazy" src="${l}" class="d-block w-100 vt-carousel-img m-0" alt="${o}">\n                    </a>\n                </div>`}),s+=`\n                </div>\n                <button class="carousel-control-prev" type="button" data-bs-target="#${n}" data-bs-slide="prev">\n                    <span class="carousel-control-prev-icon" aria-hidden="true"></span>\n                    <span class="visually-hidden">Previous</span>\n                </button>\n                <button class="carousel-control-next" type="button" data-bs-target="#${n}" data-bs-slide="next">\n                    <span class="carousel-control-next-icon" aria-hidden="true"></span>\n                    <span class="visually-hidden">Next</span>\n                </button>\n            </div>`,t.outerHTML=s})});